fd_set reads;
struct timeval tv;
int max_fd = 4;

// 1. Initialize and Set File Descriptors
FD_ZERO(&reads);
FD_SET(0, &reads);  // Monitor stdin
FD_SET(4, &reads);  // Monitor fd 4

// 2. Set Timeout (NULL means infinite wait)
tv.tv_sec = 5;      // 5 second timeout
tv.tv_usec = 0;

// 3. Call select()
int ready = select(max_fd + 1, &reads, NULL, NULL, &tv);

if (ready == 0) {
    /* Timeout occurred */
} else if (ready > 0) {
    if (FD_ISSET(0, &reads)) {
        /* fd 0 is ready for reading */
    }
}
fd_set reads;
struct timespec ts = { .tv_sec = 10 };
sigset_t sigmask;
int max_fd = 4;

FD_ZERO(&reads);
FD_SET(0, &reads);

// Prepare mask of signals to *unblock* during pselect wait
// Signals normally blocked are temporarily unblocked here
sigemptyset(&sigmask);
sigaddset(&sigmask, SIGTERM);

// pselect uses timespec and sigmask
int ready = pselect(max_fd + 1,
                    &reads, NULL, NULL,
                    &ts, &sigmask);

// Check for signal interruption
if (ready == -1 && errno == EINTR) {
    /* Signal caught and handled */
}
